insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('aacefca4-b6e4-4351-9ea2-95de44812bbe', 'situacion', 'FÍSICA', 'ctx-sit', '<p>La radiación ionizante puede consistir en partículas Alfa (α) y beta (β), así como en rayos Gamma (γ) y en rayos x. La figura muestra su poder de penetración en diferentes materiales, los cuales aumentan de izquierda a derecha su grosor. Uno de los peligros del uso de la radiación ionizante es su alto potencial de alteración del ADN de las células, por lo que se considera un agente cancerígeno.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-qradiacion.webp" style="min-width:470px" loading="lazy" alt="Penetración de radiaciones alfa, beta, X y gamma en papel, aluminio, plomo y hormigón."></figure><p>Un paciente es diagnosticado con una posible fractura en los huesos de la mano. Con el fin de evitar que el paciente sufra alteraciones por los rayos x, se irradia únicamente la mano lesionada a una baja intensidad y durante el menor tiempo necesario.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('00221e91-b106-442f-b91b-1a4270716293', 'situacion', 'FÍSICA', 'ctx-sit', '<p>La radiación ionizante puede consistir en partículas Alfa (α) y beta (β), así como en rayos Gamma (γ) y en rayos x. La figura muestra su poder de penetración en diferentes materiales, los cuales aumentan de izquierda a derecha su grosor. Uno de los peligros del uso de la radiación ionizante es su alto potencial de alteración del ADN de las células, por lo que se considera un agente cancerígeno.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b1-qradiacion.webp" style="min-width:470px" loading="lazy" alt="Penetración de radiaciones alfa, beta, X y gamma en papel, aluminio, plomo y hormigón."></figure><p>La capacidad de penetración de las radiaciones ionizantes se mide cuantificando la intensidad de energía transmitida a través de una barrera. Este valor depende del material de la barrera y de su espesor. Para radiaciones como los rayos x y los rayos γ, su intensidad energética disminuye cada vez que atraviesan un material, hasta que esta se considere despreciable; sin embargo, continúa pasando energía con alguna intensidad.</p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '45a173bd-c782-41a6-8175-3c802d7fa6ee', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  'aacefca4-b6e4-4351-9ea2-95de44812bbe', 'Ondas y sonido',
  'Además de estas medidas, ¿qué otra medida de precaución se debe implementar para disminuir el riesgo de lesionar con rayos x otras partes del paciente?',
  array['Cubrir la mayor parte del cuerpo del paciente con plomo, porque este material protegerá las células del paciente de la radiación.', 'Tener la máquina de rayos x aislada en un cuarto de hormigón, porque este material protegerá los cuerpos del personal médico de la radiación.', 'Cubrir la mayor parte del cuerpo del paciente con aluminio, porque este material protegerá las células del paciente de la radiación.', 'Tener la máquina de rayos x en un cuarto de plomo, porque este material protegerá los cuerpos del personal médico de la radiación.'],
  'Identifica a quién debe proteger la barrera y qué material muestra el esquema.', 'publicada', 'modelo', '74b276fb143815a78ef0a9e0849c1b02', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('45a173bd-c782-41a6-8175-3c802d7fa6ee', 0, 'En el modelo del cuadernillo, el plomo atenúa los rayos X y la opción lo sitúa sobre el paciente, que es el sujeto por proteger. Las opciones sobre el cuarto se refieren al personal. Esta lectura del esquema no establece protocolos clínicos actuales de protección radiológica.');

