ure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Intensidad creciente, cada vez más rápidamente, con el grosor." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">Intensidad de radiación transmitida</text><text x="284" y="191">Grosor de la barrera</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="34,181.1 82,169.6 130,149.9 178,112.2 226,38.4"/></svg></figure>', '<figure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Intensidad creciente, cada vez más lentamente, con el grosor." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">Intensidad de radiación transmitida</text><text x="284" y="191">Grosor de la barrera</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="34,182.7 58,127 94,90.9 142,64.6 226,40"/></svg></figure>'],
