insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('70c0eaf7-338c-4420-b146-9027f209dd01', 0, 'Una barrera más gruesa deja pasar menos intensidad. La curva debe ser decreciente y acercarse a un valor despreciable, tal como indica el texto. Una curva creciente o una recta horizontal no expresa esa atenuación.');

